export function t(
  locale: string,
  section: "dialogs" | "prompts" | "messages" | "status" | "palette",
  key: string,
  params?: Record<string, string>
): string {
  const norm = locale === "pt" || locale === "pt-BR" ? "pt-BR" : "en-US"
  const catalog = (builtInLocales as any)[norm] ?? builtInLocales["en-US"]
  let text = catalog?.[section]?.[key] ?? (builtInLocales["en-US"] as any)?.[section]?.[key] ?? key
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replaceAll(`{${k}}`, v)
    }
  }
  return text
}
